self.onmessage=async({data})=>{try{let result;if(data.kind==='gif'){const {encode}=await import('../assets/vendor/modern-gif.local.mjs');result=await encode(data.options);}else{const {wavPCM}=await import('./audio-core.mjs');result=wavPCM(data.channels,data.sampleRate);}self.postMessage({buffer:result},[result]);}catch(e){self.postMessage({error:e.message||'Encoding failed.'});}};
